/* Products for the team (round 41, run after part 319; before or after part 320): a team member whose permissions hold Products edits the store's catalogue from the browser as the owner does, under row level security. Three security definer functions (team_owns_product, team_owns_variant, team_variant_file_ok) answer, for the signed in account only, whether a product or a variant is in a store where they hold Products. Policies for signed in people only, never anon: products (read, add, change; never delete: a delete goes through the server, which archives a product with sales instead, as it does for the owner), product_variants (read, add, change, delete), product_variant_files (read, add, delete; a file is linked only to a variant of the product it belongs to), digital_assets (read the file's name and size; the file itself stays in the private bucket, read only by its buyers through the download routes, as before). A trigger keeps a product in its store and a variant on its product: a signed in account changes creator_id only between stores it owns, and product_id only between products of stores it owns, so a member cannot move the store's product into their own store. The service role is not held by it. Nothing changes for the owner or for visitors: the owner's own policies are left as they are and every new one only adds for team members. Safe to run again. */
DO $do$ BEGIN IF to_regprocedure('public.team_store_ids(text)') IS NULL THEN RAISE NOTICE 'part 327: team_store_ids is not here yet; run part 319 first, then this again.'; RETURN; END IF; IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 327: there is no products table here, nothing to add.'; RETURN; END IF; EXECUTE $f$create or replace function public.team_owns_product(p_product uuid) returns boolean language sql stable security definer set search_path = public as $b$ select p_product is not null and exists (select 1 from public.products p where p.id = p_product and p.creator_id in (select public.team_store_ids('products'))) $b$$f$; EXECUTE $f$create or replace function public.team_owns_variant(p_variant uuid) returns boolean language plpgsql stable security definer set search_path = public as $b$ begin if p_variant is null or to_regclass('public.product_variants') is null then return false; end if; return exists (select 1 from public.product_variants v join public.products p on p.id = v.product_id where v.id = p_variant and p.creator_id in (select public.team_store_ids('products'))); end $b$$f$; EXECUTE $f$create or replace function public.team_variant_file_ok(p_variant uuid, p_asset uuid) returns boolean language plpgsql stable security definer set search_path = public as $b$ begin if p_variant is null or p_asset is null or to_regclass('public.product_variants') is null or to_regclass('public.digital_assets') is null then return false; end if; return exists (select 1 from public.product_variants v join public.products p on p.id = v.product_id join public.digital_assets da on da.product_id = v.product_id where v.id = p_variant and da.id = p_asset and p.creator_id in (select public.team_store_ids('products'))); end $b$$f$; EXECUTE $f$create or replace function public.team_keeps_store() returns trigger language plpgsql security definer set search_path = public as $b$ declare me uuid := (select auth.uid()); begin if me is null then return new; end if; if tg_table_name = 'products' then if new.creator_id is distinct from old.creator_id and not (exists (select 1 from public.creators c where c.id = old.creator_id and c.user_id = me) and exists (select 1 from public.creators c where c.id = new.creator_id and c.user_id = me)) then raise exception 'A product stays in its store.' using errcode = '42501'; end if; elsif tg_table_name = 'product_variants' then if new.product_id is distinct from old.product_id and not (exists (select 1 from public.products p join public.creators c on c.id = p.creator_id where p.id = old.product_id and c.user_id = me) and exists (select 1 from public.products p join public.creators c on c.id = p.creator_id where p.id = new.product_id and c.user_id = me)) then raise exception 'A variant stays on its product.' using errcode = '42501'; end if; end if; return new; end $b$$f$; COMMENT ON FUNCTION public.team_owns_product(uuid) IS 'Whether this product is in a store where the signed in account is an active team member holding Products (part 327).'; COMMENT ON FUNCTION public.team_owns_variant(uuid) IS 'Whether this variant is on a product of a store where the signed in account holds Products (part 327).'; COMMENT ON FUNCTION public.team_variant_file_ok(uuid, uuid) IS 'Whether this file may be linked to this variant by a team member: the variant is in a store where they hold Products, and the file belongs to the same product (part 327).'; COMMENT ON FUNCTION public.team_keeps_store() IS 'Keeps a product in its store and a variant on its product when a signed in account changes them (part 327).'; REVOKE ALL ON FUNCTION public.team_owns_product(uuid) FROM PUBLIC, anon; REVOKE ALL ON FUNCTION public.team_owns_variant(uuid) FROM PUBLIC, anon; REVOKE ALL ON FUNCTION public.team_variant_file_ok(uuid, uuid) FROM PUBLIC, anon; REVOKE ALL ON FUNCTION public.team_keeps_store() FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.team_owns_product(uuid) TO authenticated, service_role; GRANT EXECUTE ON FUNCTION public.team_owns_variant(uuid) TO authenticated, service_role; GRANT EXECUTE ON FUNCTION public.team_variant_file_ok(uuid, uuid) TO authenticated, service_role; IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'storelib_team_keeps_store' AND tgrelid = 'public.products'::regclass) THEN CREATE TRIGGER storelib_team_keeps_store BEFORE UPDATE OF creator_id ON public.products FOR EACH ROW EXECUTE FUNCTION public.team_keeps_store(); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'products' AND policyname = 'storelib team reads products') THEN CREATE POLICY "storelib team reads products" ON public.products FOR SELECT TO authenticated USING (creator_id IN (SELECT public.team_store_ids('products'))); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'products' AND policyname = 'storelib team adds products') THEN CREATE POLICY "storelib team adds products" ON public.products FOR INSERT TO authenticated WITH CHECK (creator_id IN (SELECT public.team_store_ids('products'))); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'products' AND policyname = 'storelib team changes products') THEN CREATE POLICY "storelib team changes products" ON public.products FOR UPDATE TO authenticated USING (creator_id IN (SELECT public.team_store_ids('products'))) WITH CHECK (creator_id IN (SELECT public.team_store_ids('products'))); END IF; IF to_regclass('public.product_variants') IS NOT NULL THEN IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'storelib_team_keeps_store' AND tgrelid = 'public.product_variants'::regclass) THEN CREATE TRIGGER storelib_team_keeps_store BEFORE UPDATE OF product_id ON public.product_variants FOR EACH ROW EXECUTE FUNCTION public.team_keeps_store(); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_variants' AND policyname = 'storelib team reads variants') THEN CREATE POLICY "storelib team reads variants" ON public.product_variants FOR SELECT TO authenticated USING (public.team_owns_product(product_id)); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_variants' AND policyname = 'storelib team adds variants') THEN CREATE POLICY "storelib team adds variants" ON public.product_variants FOR INSERT TO authenticated WITH CHECK (public.team_owns_product(product_id)); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_variants' AND policyname = 'storelib team changes variants') THEN CREATE POLICY "storelib team changes variants" ON public.product_variants FOR UPDATE TO authenticated USING (public.team_owns_product(product_id)) WITH CHECK (public.team_owns_product(product_id)); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_variants' AND policyname = 'storelib team deletes variants') THEN CREATE POLICY "storelib team deletes variants" ON public.product_variants FOR DELETE TO authenticated USING (public.team_owns_product(product_id)); END IF; END IF; IF to_regclass('public.product_variant_files') IS NOT NULL THEN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_variant_files' AND policyname = 'storelib team reads variant files') THEN CREATE POLICY "storelib team reads variant files" ON public.product_variant_files FOR SELECT TO authenticated USING (public.team_owns_variant(variant_id)); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_variant_files' AND policyname = 'storelib team links variant files') THEN CREATE POLICY "storelib team links variant files" ON public.product_variant_files FOR INSERT TO authenticated WITH CHECK (public.team_variant_file_ok(variant_id, digital_asset_id)); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_variant_files' AND policyname = 'storelib team unlinks variant files') THEN CREATE POLICY "storelib team unlinks variant files" ON public.product_variant_files FOR DELETE TO authenticated USING (public.team_owns_variant(variant_id)); END IF; END IF; IF to_regclass('public.digital_assets') IS NOT NULL THEN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'digital_assets' AND policyname = 'storelib team reads file details') THEN CREATE POLICY "storelib team reads file details" ON public.digital_assets FOR SELECT TO authenticated USING (public.team_owns_product(product_id)); END IF; END IF; END $do$;
notify pgrst, 'reload schema';
